#!/usr/bin/env node
/**
 * agy-director.mjs — الوسيط الموسَّع لمهارة `antigravity-delegate`.
 *
 * يضيف على scripts/relay.mjs(original):
 *   - --dangerously-skip-permissions (ضروري headless: بدونه AGY يعلّق على الموافقات)
 *   - سلّم موديلات تلقائي (ladder) مع اكتشاف نفاد الحصة (RESOURCE_EXHAUSTED) والتبديل
 *   - استخراج conversationId من stdout أو من brain dir الأحدث
 *   - result.json منظّم (role/modelReal/conversationId/artifacts/stdoutPath)
 *
 * ملاحظات مُقاسة:
 *   - `-p` يطلب قيمة (الـ prompt) — لا يقبل stdin لوحده.
 *   - `--effort` غير مدعوم لاسماء claude / gpt-oss (المستوى مُدمج في اسم الموديل).
 *   - AGY يرجع 429 "Individual quota reached" للموديلات المدفوعة → نسقّط للـ gemini.
 *
 * الاستخدام:
 *   node agy-director.mjs --role plan|review|implement --brief <file.md> \
 *        [--cd <dir>] [--model auto|<name>] [--session <conv-id>] [--timeout 20m] [--out f.json]
 */
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";

const argv = process.argv.slice(2);
const arg = (k, d = null) => {
  const i = argv.indexOf(`--${k}`);
  return i !== -1 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d;
};
const has = (k) => argv.includes(`--${k}`);

const role = arg("role", "plan");
const briefPath = arg("brief");
const cwd = path.resolve(arg("cd", process.cwd()));
const modeArg = arg("mode", null);
const session = arg("session", null);
const outFile = arg("out");

const UNITS = { m: 60000, s: 1000, h: 3600000 };
const tMatch = (arg("timeout", "12m").match(/(\d+)\s*([msh])/i) || [null, "12", "m"]);
const timeoutMs = Number(tMatch[1]) * (UNITS[tMatch[2].toLowerCase()] || 60000);

const LADDER = ["claude-opus-4-6-thinking", "claude-sonnet-4-6", "gemini-3.8-flash-high", "gemini-3.8-flash-medium", "gemini-3.8-flash-low"];
const modelArg = arg("model", "auto");
const modelLadder = modelArg === "auto" ? LADDER : [modelArg];

if (!briefPath || !fs.existsSync(briefPath)) {
  console.error("✗ --brief مطلوب وملفه لازم يكون موجود: " + (briefPath || "(مفقود)"));
  process.exit(2);
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const workDir = path.join(os.tmpdir(), "agy-director", `${role}-${stamp}`);
fs.mkdirSync(workDir, { recursive: true });
const stdoutPath = path.join(workDir, "stdout.md");
const stderrPath = path.join(workDir, "stderr.log");
const briefCopy = path.join(workDir, "brief.md");
fs.copyFileSync(briefPath, briefCopy);
const briefText = fs.readFileSync(briefCopy, "utf8");
const MODE_BY_ROLE = { plan: "plan", review: "plan", implement: "accept-edits" };

